package cn.bidcheck.verification.facts;

import cn.bidcheck.domain.Domain.*;
import cn.bidcheck.ocr.OcrLayout;
import java.util.*;
import org.junit.jupiter.api.Test;
import static cn.bidcheck.verification.facts.LedgerValues.*;
import static cn.bidcheck.verification.facts.StructuralFixtures.*;
import static org.junit.jupiter.api.Assertions.*;

class StructuralLedgerTest {
    @Test void layoutOnlyChangeInvalidatesOldOccurrencesAndParserFingerprint(){cn.bidcheck.verification.facts.FactLedgerServiceTest helper=new FactLedgerServiceTest();cn.bidcheck.domain.Domain.Document d=helper.doc("d","合成甲：一级");helper.publish("run","cp",cn.bidcheck.compat.Java8Api.listOf(d),helper.batch(cn.bidcheck.compat.Java8Api.listOf(helper.fact("f","一级","S")),cn.bidcheck.compat.Java8Api.listOf(helper.source(d,"S"))));cn.bidcheck.domain.Domain.Page page=d.pages().get(0);cn.bidcheck.domain.Domain.Page next=new Page(page.number(),page.text(),page.locationType(),page.parser(),page.warning(),OcrLayout.unavailable("结构版本已重新解析"));cn.bidcheck.domain.Domain.Document newDoc=new Document(d.id(),d.projectId(),d.role(),d.name(),d.version(),d.sha256(),"",cn.bidcheck.compat.Java8Api.listOf(next),cn.bidcheck.compat.Java8Api.listOf());assertNotEquals(FactLedgerService.parserFingerprint(page),FactLedgerService.parserFingerprint(next));assertTrue(helper.lookup(cn.bidcheck.compat.Java8Api.listOf(newDoc)).isEmpty());}
    @Test void nativeRowIdentityAndChainProofAreRecomputedAndFrozen(){cn.bidcheck.verification.facts.FactLedgerServiceTest helper=new FactLedgerServiceTest();cn.bidcheck.verification.facts.StructuralFixtures.Fixture fixture=row(1,false,false,ID,"2025-01、2025-02、2025-03");cn.bidcheck.domain.Domain.Document d=helper.doc("d",fixture.text());java.util.Map<java.lang.String, java.lang.Object> fact=helper.fact("f","缴费月份","S");fact.put("kind","MONTHS");fact.put("subject",NAME);fact.put("attributes",of("person",NAME,"months",cn.bidcheck.compat.Java8Api.listOf("2025-01", "2025-02", "2025-03"),"cellIds",ids(fixture),"structureProof",cn.bidcheck.compat.Java8Api.mapOf("status", "MODEL_FORGED")));
        java.util.Map<java.lang.String, java.lang.Object> batch=helper.batch(cn.bidcheck.compat.Java8Api.listOf(fact),cn.bidcheck.compat.Java8Api.listOf(helper.source(d,"S")));batch.put("layoutCells",fixture.cells());batch.put("layoutIdentity","test-layout-1");assertEquals(1,helper.publish("run","cp",cn.bidcheck.compat.Java8Api.listOf(d),batch).get("accepted"));java.util.Map<java.lang.String, java.lang.Object> result=helper.lookup(cn.bidcheck.compat.Java8Api.listOf(d)).get(0);assertEquals("STRONG",result.get("identityStrength"));assertTrue(canonical(result).contains("SOURCE_BOUND"));assertFalse(canonical(result).contains("MODEL_FORGED"));java.util.Map<java.lang.String, java.lang.Object> snapshot=helper.ledger.snapshot("project","run","engine-identity",cn.bidcheck.compat.Java8Api.listOf(d));fixture.cells().clear();assertEquals(snapshot,helper.view("run",cn.bidcheck.compat.Java8Api.listOf(d)));}
    @Test void inventedModelStructureProofCannotUpgradeIdentityWithoutLayout(){cn.bidcheck.verification.facts.FactLedgerServiceTest helper=new FactLedgerServiceTest();cn.bidcheck.domain.Domain.Document d=helper.doc("d","合成人甲 缴费月份2025-01");java.util.Map<java.lang.String, java.lang.Object> fact=helper.fact("f","缴费月份","S");fact.put("kind","MONTHS");fact.put("subject",NAME);fact.put("attributes",of("person",NAME,"structureProof",cn.bidcheck.compat.Java8Api.mapOf("status", "SOURCE_BOUND", "identityStrength", "STRONG")));helper.publish("run","cp",cn.bidcheck.compat.Java8Api.listOf(d),helper.batch(cn.bidcheck.compat.Java8Api.listOf(fact),cn.bidcheck.compat.Java8Api.listOf(helper.source(d,"S"))));java.util.Map<java.lang.String, java.lang.Object> out=helper.lookup(cn.bidcheck.compat.Java8Api.listOf(d)).get(0);assertEquals("SOURCE_LOCAL",out.get("identityStrength"));assertFalse(map(map(out.get("fact")).get("attributes")).containsKey("structureProof"));}
}
